{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C28"],
      "claim": "dOTC, a close oxathiolane cytidine analogue differing only by O/S ring positions, achieved 16.5% CSF/serum after oral dosing in rats and was classified as BBB-permeable, directly supporting meaningful CNS access for the query scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Cytarabine, a cytidine nucleoside analogue, showed a mean CSF:plasma ratio of 0.58 after i.v. administration in dogs, demonstrating that cytidine analogues can achieve substantial CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "L-2'-Fd4C, a deoxycytidine analogue, was detected in monkey CSF after oral dosing at levels exceeding the antiviral EC50, supporting meaningful CNS penetration for this nucleoside class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "PSI-6130, a cytidine analogue, was detected in rhesus monkey CSF after administration, providing additional evidence that cytidine-based nucleosides can cross the blood-brain barrier.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Gemcitabine, a gem-difluorinated cytidine analogue, had a mean CSF:plasma ratio of 6.7% and was considered poorly penetrating, representing a contradictory example whose structural differences reduce transferability to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C01"],
      "claim": "NHC, a ribonucleoside analogue, showed a very low brain distribution ratio of 0.8%, but its ribose-based structure and lower similarity limit its relevance to the oxathiolane cytidine query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The closest analogue dOTC shows 16.5% CSF/serum and is BBB-permeable, and multiple cytidine nucleoside analogues (ara-C, L-Fd4C, PSI-6130) show measurable CSF exposure. Contradictory poor-penetration examples are structurally more distant. Therefore lamivudine is predicted to have meaningful CNS access.",
  "evidence_gaps": [
    "No direct lamivudine-specific CSF/plasma measurement is included in the provided evidence set.",
    "The impact of efflux transporters on the query's CNS exposure is not directly measured in the retrieved records."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

